cat > /tmp/ivx-final-verify.mjs <<'EOF'
import { chromium } from 'playwright';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 375, height: 812 } });

const errors = [];
page.on('pageerror', e => errors.push(e.message.slice(0, 200)));
page.on('console', msg => {
  if (msg.type() === 'error') errors.push(`[CONSOLE ERROR] ${msg.text().slice(0, 200)}`);
});

const res = await page.goto('https://ivxholding.com/app/', { waitUntil: 'networkidle' });
await page.waitForTimeout(8000);

const html = await page.content();
const text = await page.evaluate(() => document.body.innerText?.slice(0, 800));
const bodyStyles = await page.evaluate(() => {
  const root = document.getElementById('root');
  const textEls = Array.from(document.querySelectorAll('div, span, p'))
    .filter(el => {
      const rect = el.getBoundingClientRect();
      return el.innerText && el.innerText.trim().length > 0 && rect.width > 0 && rect.height > 0;
    })
    .slice(0, 5);
  return {
    rootBg: root ? window.getComputedStyle(root).backgroundColor : 'N/A',
    rootColor: root ? window.getComputedStyle(root).color : 'N/A',
    textElements: textEls.map(el => ({
      text: el.innerText.slice(0, 40),
      color: window.getComputedStyle(el).color,
      bg: window.getComputedStyle(el).backgroundColor,
    })),
    hasBlankApp: !!document.body.innerText?.match(/Welcome to Your Blank App/i),
  };
});

await page.screenshot({ path: '/tmp/ivx-final-live.png', fullPage: false });

await browser.close();

console.log('URL: https://ivxholding.com/app/');
console.log('HTTP status:', res.status());
console.log('Has "Welcome to Your Blank App":', bodyStyles.hasBlankApp);
console.log('\n=== STYLES ===');
console.log(JSON.stringify(bodyStyles, null, 2));
console.log('\n=== RENDERED TEXT ===');
console.log(text);
console.log('\n=== ERRORS ===');
errors.slice(0, 5).forEach(e => console.log(e));
EOF
bun run /tmp/ivx-final-verify.mjs

